package com.vibeguard.samples.webhooks; import java.nio.charset.StandardCharsets; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Verifies provider webhook signatures before retaining events. */ @RestController @RequestMapping("/webhooks/payments") public class PaymentWebhookController { private final List<String> events=new ArrayList<>(); @Value("${PAYMENT_WEBHOOK_SECRET:}") private String secret; @PostMapping public ResponseEntity<Void> receive(@RequestHeader("X-Payment-Signature") String signature,@RequestBody String body)throws Exception{if(secret.isBlank()||!signature(body).equals(signature))return ResponseEntity.status(401).build();events.add(body);return ResponseEntity.accepted().build();}@GetMapping public List<String> list(){return List.copyOf(events);}private String signature(String body)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));} }
